E=Path(os.environ.get('DENISE_PSV_EVIDENCE_ROOT',W/'benchmark-results/psv-multishot')).resolve()
D=E/'b3s-r5-20261122';OLD=E/'b3s-r3-r4'
spec=importlib.util.spec_from_file_location('b3r3',W/'benchmarks/psv_multishot_b3s.py');b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
b.D=D;b.FILTER=OLD/'production-filter';b.tau_contract=lambda:json.loads((OLD/'preparation.json').read_text())['tau_contract']
TRAIN=(1,26,51,76,100);CONTROL=(38,63);SHOTS=TRAIN+CONTROL;FREQUENCIES=(2.5,3.5,5.)
EXPECTED={'denise':'4ebd039a9068a91f8b654a8f946b84997229ffb6fb0920c85f75a117c5c7f463','denise_cuda':'f7c5d91c479b0ceebcc3b27e4028a7681da1a3dd05befa720390bbf7c51ba56d','legacy':'13cde93ef0d169a73241f1a12c181002091290df23334b9a53a7d87971055fa0'}
BINARY={'cpu':W/'bin/denise','cuda':W/'bin/denise_cuda','koehn':OLD/'koehn-b07d81d/bin/denise'}
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(name,value):
 p=D/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,indent=2,allow_nan=False));return p

def pins():
 for backend,key in [('cpu','denise'),('cuda','denise_cuda'),('koehn','legacy')]:assert sha(BINARY[backend])==EXPECTED[key],backend
 git=['git','-C',str(W)];env=os.environ.copy();env['GIT_OPTIONAL_LOCKS']='0'
 ref=subprocess.check_output(git+['rev-parse','HEAD'],text=True,env=env).strip()
 # R5 may add benchmark-only commits. Compare protected committed blobs,
 # avoiding repeated full CRLF scans across the Windows mount. The initial
 # full native worktree diff is also recorded before numerical execution.
 subprocess.run(git+['diff','--quiet','--no-ext-diff','be7b76960e658d6149ad09add88c963a4cc6dbe9',ref,'--','src','include','tests','libcseife'],check=True,env=env)
 return {k:sha(v) for k,v in BINARY.items()}

def params(case,updates):
 p=case/'denise.inp';p.write_text(b.replace_parameters(p.read_text(),updates))
def flow(case,updates):
 p=case/'workflow.inp';lines=p.read_text().splitlines();names=lines[0].split()
 for i in range(1,len(lines)):
  row=lines[i].split()
  for k,v in updates.items():row[names.index(k)]=str(v)
  lines[i]=' '.join(row)
 p.write_text('\n'.join(lines)+'\n')
def case(name,backend,mode,*,model=None,shots=SHOTS,stages=FREQUENCIES,iterations=25,source=None,q30=False):
 c,layout=b.write_case(name,backend,mode,model=model or D/'models/start',shots=shots,stages=stages,iterations=iterations,stage_source=source,observed=False)
 rows=(c/'source.dat').read_text().splitlines();out=[]
 for line in rows[1:]:
  a=line.split();a[2]='220.0';assert 200<float(a[0])<=9800;out.append(' '.join(a))
 (c/'source.dat').write_text(rows[0]+'\n'+'\n'.join(out)+'\n')
 recs=[l.split() for l in (c/'receivers.dat').read_text().splitlines()];assert len(recs)==400
 assert all(200<float(a[0])<=9800 for a in recs)
 (c/'receivers.dat').write_text(''.join(f'{a[0]} 240.0\n' for a in recs))
 if mode==1:params(c,{'MIN_ITER':4,'EPS_SCALE':.01,'STEPMAX':6,'SCALEFAC':2.})
 if q30:
  for field in ['qp','qs']:np.full((500,152),30.,dtype='<f4').tofile(c/'start'/('model.'+field))
  if backend!='koehn':params(c,{'Q_PARAMETERIZATION_MODE':0})
 return c,layout

def bindings(c):
 files=[c/'denise.inp',c/'workflow.inp',c/'source.dat',c/'receivers.dat',*sorted((c/'start').glob('model.*')),*sorted(c.glob('observed*.su.shot*')),*sorted((c/'wavelet').glob('external*'))]
 # Exclude readback diagnostics generated by the solver.
 return {str(p.relative_to(c)):sha(p) for p in files if '.fdveps.' not in p.name and '_source_signal' not in p.name}
def check_bindings(c,wanted):assert bindings(c)==wanted,('input drift',c)

def errors(model):
 ans={};bands={'total':np.arange(152),'upper':np.arange(51),'middle':np.arange(51,102),'lower':np.arange(102,152)}
 for field in ['vp','vs']:
  truth=np.fromfile(D/'models/truth'/('model.'+field),dtype='<f4').reshape(500,152).astype(np.float64)
  a=np.fromfile(model/('model.'+field),dtype='<f4').reshape(500,152).astype(np.float64);assert np.isfinite(a).all()
  ans[field]={}
  for name,idx in bands.items():
   delta=(a-truth)[:,idx];t=truth[:,idx]
   ans[field][name]={'relative_l2':float(np.sqrt(np.sum(delta*delta,dtype=np.float64)/np.sum(t*t,dtype=np.float64))),'rmse_m_s':float(np.sqrt(np.mean(delta*delta))),'rows_1based':[int(idx[0])+1,int(idx[-1])+1]}
 return ans

def prepare():
 D.mkdir(exist_ok=True);pins()
 for role in ['start','truth']:
  dest=D/'models'/role;dest.mkdir(parents=True)
  for field in ['vp','vs','rho','qp','qs']:
   src=OLD/'models'/role/('model.'+field);out=dest/src.name;shutil.copyfile(src,out);assert sha(src)==sha(out)
 for fc in FREQUENCIES:
  impulse=np.zeros((1,3000),dtype='<f4');impulse[0,0]=1.
  source=b.filtered(b.filtered(impulse,5,15.,-5.),6,fc)
  p=D/f'stage-source-{fc}.dat';p.write_text(''.join(f'{float(v):.9e}\n' for v in source[0]))
  assert np.array([float(l) for l in p.read_text().splitlines()],dtype='<f4').tobytes()==source.tobytes()
 jobs={}
 def add(name,backend,mode,**kw):
  c,layout=case(name,backend,mode,**kw);jobs[name]={'backend':backend,'layout':layout,'mode':mode}
 add('bank','cuda',0,model=D/'models/truth')
 add('main-gpu','cuda',1,shots=TRAIN)
 add('cpu-four','cpu',1,shots=TRAIN,stages=(2.5,),iterations=4)
 add('compare-candidate-shot51','cpu',0,model=D/'models/truth',shots=(51,),q30=True)
 add('compare-koehn-shot51','koehn',0,model=D/'models/truth',shots=(51,),q30=True)
 for fc in FREQUENCIES:
  add(f'cal-gradient-{fc}','cuda',1,shots=TRAIN,stages=(fc,),iterations=3)
  add(f'cal-forward-{fc}','cuda',0,shots=TRAIN,source=D/f'stage-source-{fc}.dat',stages=(fc,))
 save('jobs.json',jobs)
 save('preparation.json',{'model_bytes_unchanged':True,'models':{str(p.relative_to(D)):sha(p) for p in sorted((D/'models').glob('*/*'))},'initial_errors':errors(D/'models/start'),'source_rows':[11],'receiver_rows':[12],'coordinates_m':{'source_y':220,'receiver_y':240,'training_x':[800,2800,4800,6800,8720],'control_x':[3760,5760],'receivers_x':[800,8780,20]},'source_count':7,'receiver_count':400,'lateral_removals':0,'taper':'disabled: existing legacy taper branches are bypassed by exact path; no production change','source_ascii_fp32_roundtrip':True})
 print('Prepared R5 inputs, no solver launched.',flush=True)

def archive_lifecycle(c):
 p=c/'jacobian/gradient.active_fwi.json'
 try:r=json.loads(p.read_text())
 except (OSError,json.JSONDecodeError):return
 match=re.search(r'_stage_(\d+)_it_(\d+)$',r['persisted_prefix']);assert match,r
 out=c/'lifecycle'/f'stage{match[1]}-iter{match[2]}.json';out.parent.mkdir(exist_ok=True)
 if not out.exists():out.write_text(json.dumps(r,indent=2,allow_nan=False))

def _owned_state(pid):
 try:
  if Path(f'/proc/{pid}').stat().st_uid!=os.getuid():return None
  text=Path(f'/proc/{pid}/stat').read_text();parts=text[text.rfind(')')+2:].split();return (parts[19],parts[0])
 except (OSError,IndexError):return None

def _bounded_reap(process):
 owned={pid:_owned_state(pid) for pid in b.descendants(process.pid)}
 if process.poll() is None:
  try:os.killpg(process.pid,signal.SIGTERM)
  except ProcessLookupError:pass
  try:process.wait(timeout=8)
  except subprocess.TimeoutExpired:
   try:os.killpg(process.pid,signal.SIGKILL)
   except ProcessLookupError:pass
   process.wait(timeout=8)
 for pid,previous in owned.items():
  current=_owned_state(pid)
  if previous and current and current[0]==previous[0] and current[1]!='Z':
   try:os.kill(pid,signal.SIGKILL)
   except ProcessLookupError:pass
 process.wait(timeout=8)
 deadline=time.monotonic()+8
 while time.monotonic()<deadline:
  live=[pid for pid,old in owned.items() if old and (now:=_owned_state(pid)) and now[0]==old[0] and now[1]!='Z']
  if not live:return []
  time.sleep(.1)
 return live

def run(c,backend,layout,*,timed=False,gradient_only=False,main=False):
 pins();assert not (c/'stdout.log').exists() and not (c/'run.json').exists(),('Preserve existing/partial run, do not duplicate',c)
 binary=D/'timing-denise-cuda' if timed else BINARY[backend];cap=2700. if main else 1800.;stop_at=cap-30.
 command=['mpiexec','--oversubscribe','-np',str(layout[0]*layout[1]),str(binary),'denise.inp','workflow.inp']
 env=os.environ.copy();env.update(CUDA_VISIBLE_DEVICES='0',OMP_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',DENISE_PSV_BACKEND='cuda' if backend=='cuda' else 'cpu',DENISE_PSV_EXACT_SEGMENTS='8',GIT_CEILING_DIRECTORIES=str(W.parent))
 for key in ['DENISE_PSV_EXACT_VISCO_GRADIENT','DENISE_PSV_EXACT_DISTRIBUTED_GRADIENT_ONLY','DENISE_CUDA_PSV_TEST_USE_RAW_MODELED_OBSERVED','DENISE_PSV_DIAGNOSTIC_CPU_RESIDUAL','DENISE_PSV_EXACT_FULL_STORAGE_REFERENCE']:env.pop(key,None)
 if gradient_only:env['DENISE_PSV_EXACT_DISTRIBUTED_GRADIENT_ONLY']='1'
 if timed:env['DENISE_PSV_R5_TIMING_FILE']=str(c/'timing.csv')
 wanted=bindings(c);frozen=D/'criteria-input-freeze.json'
 if frozen.exists():
  contract=json.loads(frozen.read_text());expected=contract['cases'].get(c.name)
  if expected:check_bindings(c,expected['input_sha256'])
 info={'production_source':'200b3b8c4cb7c3141e8e5bde0af1db17c8c3b590','harness_sha256':sha(__file__),'binary':str(binary),'binary_sha256':sha(binary),'command':command,'backend':backend,'layout':layout,'input_sha256':wanted,'gradient_only':gradient_only,'timing_only_binary':timed,'wall_budget_seconds':cap,'guard_threshold_seconds':stop_at,'rss_budget_bytes':8*1024**3}
 started=time.monotonic();peak=0;gpu_peak=None;last_gpu=0;reason=None;events=[];known_rows=0;telemetry_misses=0;process=None;remaining=[];monitor_error=None
 try:
  with (c/'stdout.log').open('w') as out,(c/'stderr.log').open('w') as err:
   process=subprocess.Popen(command,cwd=c,env=env,stdout=out,stderr=err,start_new_session=True)
   info.update(pid=process.pid,started_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()));save('active-run.json',dict(case=str(c),**info))
   while process.poll() is None:
    archive_lifecycle(c);rss=0
    for pid in b.descendants(process.pid):
     try:rss+=int(Path(f'/proc/{pid}/statm').read_text().split()[1])*os.sysconf('SC_PAGE_SIZE')
     except (OSError,IndexError):pass
    peak=max(peak,rss)
    try:rows=len((c/'misfit.log').read_text().splitlines())
    except FileNotFoundError:rows=0
    if rows>known_rows:events.append({'rows':rows,'seconds':time.monotonic()-started});known_rows=rows
    if backend=='cuda' and time.monotonic()-last_gpu>1.:
     try:
      q=subprocess.run(['nvidia-smi','--query-gpu=memory.used','--format=csv,noheader,nounits'],text=True,capture_output=True,timeout=.5)
      gpu_peak=max(gpu_peak or 0,int(q.stdout.strip().splitlines()[0]))
     except (subprocess.TimeoutExpired,OSError,ValueError,IndexError):telemetry_misses+=1
     last_gpu=time.monotonic()
    if rss>=8*1024**3:reason='8GiB aggregate descendant Host-RSS guard'
    if time.monotonic()-started>=stop_at:reason=f'{cap:g}s wall guard (30s cleanup reserve)'
    if reason:break
    time.sleep(.1)
 except BaseException as exc:
  monitor_error=repr(exc);reason='monitor/IO exception: '+monitor_error
 finally:
  if process is not None:remaining=_bounded_reap(process)
 # Always reap before reading/writing final analysis; telemetry failure alone
 # cannot remove supervision. No process from a failed monitor is abandoned.
 archive_lifecycle(c)
 info.update(returncode=process.returncode if process else None,runtime_seconds=time.monotonic()-started,ended_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),peak_aggregate_host_rss_bytes=peak,gpu_device_total_peak_mib=gpu_peak,gpu_telemetry_misses=telemetry_misses,gpu_memory_scope='nvidia-smi whole-device total sampled1s when available; host descendant RSS sampled0.1s',stop_reason=reason,monitor_error=monitor_error,misfit_row_events=events,process_reaped=process is not None and process.poll() is not None,remaining_owned_live_pids=remaining)
 (c/'run.json').write_text(json.dumps(info,indent=2,allow_nan=False));save('active-run.json',{'active':bool(remaining),'last_case':str(c),'returncode':info['returncode'],'remaining_owned_live_pids':remaining})
 assert not remaining,('Own children remain: stop further jobs',remaining)
 check_bindings(c,wanted);print(c.name,info['returncode'],info['runtime_seconds'],peak/1024**3,flush=True)
 if monitor_error:raise RuntimeError(monitor_error)
 return info

def bank():
 c=D/'bank';job=json.loads((D/'jobs.json').read_text())['bank'];r=run(c,job['backend'],tuple(job['layout']));assert r['returncode']==0,r
 raw={str(p.relative_to(c)):sha(p) for p in sorted((c/'su').glob('synthetic*'))};assert len(raw)==14
 for k in range(1,8):
  for comp in ['x','y']:assert np.isfinite(b.su(c/'su'/f'synthetic_{comp}.su.shot{k}')).all()
 save('bank.json',raw)
 # Only training files enter inversion/calibration directories.
 for name,job in json.loads((D/'jobs.json').read_text()).items():
  if job['mode']!=1:continue
  for local,shot in enumerate(TRAIN,1):
   for comp in ['x','y']:shutil.copyfile(c/'su'/f'synthetic_{comp}.su.shot{SHOTS.index(shot)+1}',D/name/f'observed_{comp}.su.shot{local}')

