 value={'packet_sha256':'8045517a40001f28d0a26d07aed5bd5c7826a919cf75b6188a14db550d562346','base_candidate':'be7b76960e658d6149ad09add88c963a4cc6dbe9','base_tree':'9853af12a5f412cf5a95a2ed16844485186617b5','created_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'harness_source_sha256':sha(__file__),'timing_binary_sha256':sha(D/'timing-denise-cuda'),'timing_hook_sources_sha256':{str(p.relative_to(W)):sha(p) for p in [W/'benchmarks/psv_multishot_r5_timing_adapter.c',W/'benchmarks/psv_multishot_r5_timing_dispatch.c']},'binaries':pins(),'cases':{name:dict(**job,input_sha256=bindings(D/name)) for name,job in jobs.items()},'observed_bank_sha256':json.loads((D/'bank.json').read_text()),'initial_errors':initial,'model_ratio_precheck_sha256':sha(D/'model-ratio-precheck.json'),'objective':{'formula':'0.5 sum_shot,receiver,component,t=2..NT-1 [F(m;Bq)-Bd]^2','filter':'unchanged production apply_tdfilt/Butterworth; source once and observed once; no second synthetic/residual filter','arithmetic':'FP32 synthetic-observed residual; FP64 squares/sums, common external implementation','training':TRAIN,'control':CONTROL,'frequencies_hz':FREQUENCIES},'criteria':{'K1':'normal program completion through all3 stages,1..25 iterations each, all persisted models/production misfits/trial objectives finite','K2':'external training final<initial separately at each stage frequency','K3':'external sum of controls38+63 final<initial separately at each stage frequency','K4':{'global_vs_final_lt':initial['vs']['total']['relative_l2'],'upper_vs_final_le':.98*initial['vs']['upper']['relative_l2'],'upper_vs_also_strict_lt':initial['vs']['upper']['relative_l2'],'middle_vs_final_lt':initial['vs']['middle']['relative_l2'],'upper_required_relative_improvement':.02},'K5':{'global_vp_final_le':initial['vp']['total']['relative_l2']},'K6':'all5 CPU model fields after first4 iterations at2.5Hz byte-identical to GPU after same4 steps'},'error_definition':'L2(model-truth)/L2(truth), float64, whole500x152 crop including CPML; rows upper1..51 middle52..102 lower103..152; same depth bands asR3','controls_never_inverted':True,'parameters':{'ITERMAX':25,'MIN_ITER':4,'EPS_SCALE':.01,'STEPMAX':6,'max_trial_batches':7,'SCALEFAC':2,'PRO':0,'N_ORDER':0,'Q_mode':1,'Qp_Qs_physical':80,'FL':3,'Q_fit':[1,10,.25],'segments':8,'gradient_source_taper':False,'stopping_semantics':'production unchanged, including exact-active control flow; no new Pro/early-stop implementation'},'calibration':{'updates':'none:3 gradient-only sweeps at unchanged start per frequency, plus one5-shot stage-source MODE0 forward per frequency','metric':'G=max steady gradient-sweep wall(second/third row intervals)+0.2s. Outside=max(0,steady wall-sum dispatcher+finish). F=max sum five forward dispatcher times+Outside+0.2s. Setup=max complete calibration-gradient runtime. Bound=1.25*(Setup+75*(G+7*F)). Stop before main if bound>=2700s or RSS>=8GiB. No parameter adjustment after outputs.','reserve_factor':1.25,'sampling_uncertainty_seconds':.2},'figures':{'units':'m/s;color limits fixed from start+truth before inversion; axes km','colormap':'viridis','limits':{f:[min(float(np.fromfile(D/'models/start'/('model.'+f),dtype='<f4').min()),float(np.fromfile(D/'models/truth'/('model.'+f),dtype='<f4').min())),max(float(np.fromfile(D/'models/start'/('model.'+f),dtype='<f4').max()),float(np.fromfile(D/'models/truth'/('model.'+f),dtype='<f4').max()))] for f in ['vp','vs']}},'forward_check':{'source':51,'unfiltered':True,'candidate':'CPU4x2 legacy-Q mode0 inputQ30 -> tau=float32(2/30); sole comparator forward only','legacy':'R3-built b07d81d + existing package inseis bounds fix, forcedQ30','FL':3,'time_samples':'2..NT-1','max_relative_l2_per_component':1e-3,'not_a_K1_K6_replacement':True}}
 value['protected_source_audit_sha256']=sha(D/'protected-source-audit.json')
