def build():
 pins();log=D/'timing-build.log';commands=[]
 for kind in ['dispatch','adapter']:
  commands.append(['mpicc','-O3','-w','-fno-stack-protector','-D_FORTIFY_SOURCE=0','-fcommon','-std=c99','-I../libcseife','-I../include','-c',str(W/f'benchmarks/psv_multishot_r5_timing_{kind}.c'),'-o',str(D/f'timing_{kind}.o')])
 commands.append(['make','denise_cuda','NVCC=/usr/local/cuda/bin/nvcc','CUDA_ARCHS=86','CUDA_PSV_FMAD=false','CUDA_DENISE_BIN='+str(D/'timing-denise-cuda'),'CUDA_PSV_DISPATCH_OBJ='+str(D/'timing_dispatch.o'),'CUDA_PSV_EXACT_FWI_OBJ='+str(D/'timing_adapter.o')])
 with log.open('w') as f:
  for cmd in commands:
   f.write(json.dumps(cmd)+'\n');f.flush();subprocess.run(cmd,cwd=W/'src',stdout=f,stderr=subprocess.STDOUT,check=True,timeout=600)
 pins();save('timing-build.json',{'commands':commands,'binary_sha256':sha(D/'timing-denise-cuda'),'sources':{str(p.relative_to(W)):sha(p) for p in [W/'benchmarks/psv_multishot_r5_timing_dispatch.c',W/'benchmarks/psv_multishot_r5_timing_adapter.c']},'scope':'private timing-only host hooks; all arguments/operator calls unmodified; original shared objects/core NoFMA; production binaries unchanged'})

def timing_rows(c):
 result=[]
 for line in (c/'timing.csv').read_text().splitlines():
  phase,seconds,code,mode=line.split(',');assert int(code)==1,line
  result.append({'phase':phase,'seconds':float(seconds),'mode':int(mode)})
 return result

def calibrate():
 assert (D/'criteria-input-freeze.json').exists();results={};G=[];outside=[];F=[];setup=[]
 for fc in FREQUENCIES:
  c=D/f'cal-gradient-{fc}';info=run(c,'cuda',(1,1),timed=True,gradient_only=True);assert info['returncode']==0,info
  rows=timing_rows(c);assert len(rows)==30 and [r['phase'] for r in rows]==['dispatch','finish']*15
  events=info['misfit_row_events'];assert [v['rows'] for v in events]==[1,2,3],events
  steady=[events[i]['seconds']-events[i-1]['seconds'] for i in [1,2]];hot=[sum(r['seconds'] for r in rows[i*10:(i+1)*10]) for i in range(3)]
  G.extend(steady);outside.extend(max(0.,steady[i]-hot[i+1]) for i in range(2));setup.append(info['runtime_seconds'])
  f=D/f'cal-forward-{fc}';fi=run(f,'cuda',(1,1),timed=True);assert fi['returncode']==0,fi
  fr=timing_rows(f);assert len(fr)==5 and all(r['phase']=='dispatch' for r in fr);F.append(sum(r['seconds'] for r in fr))
  results[str(fc)]={'gradient':info,'gradient_hot_seconds_by_sweep':hot,'steady_wall_seconds':steady,'forward':fi,'forward_dispatch_batch_seconds':F[-1]};save('calibration-progress.json',results)
  lower_bound=1.25*(max(setup)+75*(max(G)+.2))
  if lower_bound>=2700.:
   save('calibration.json',{'status':'RESOURCE_STOP_BEFORE_MAIN','criteria_freeze_sha256':sha(D/'criteria-input-freeze.json'),'measurements':results,'G_seconds':max(G)+.2,'frozen_estimate_lower_bound_with_F_zero_seconds':lower_bound,'interpretation':'Lower bound of frozen conservative estimator only, not a hard lower bound on real runtime; missing band maxima and trial allowance cannot reduce it','within_45min':False,'within_8GiB':max(v['gradient']['peak_aggregate_host_rss_bytes'] for v in results.values())<8*1024**3,'main_started':False,'cpu_four_started':False})
   print('RESOURCE STOP: frozen estimate already exceeds45min',lower_bound,flush=True);return

 g=max(G)+.2;non=max(outside);f=max(F)+non+.2;bound=1.25*(max(setup)+75*(g+7*f));peak=max(v['gradient']['peak_aggregate_host_rss_bytes'] for v in results.values())
 result={'criteria_freeze_sha256':sha(D/'criteria-input-freeze.json'),'measurements':results,'G_seconds':g,'F_seconds':f,'max_outside_gpu_gradient_seconds':non,'setup_allowance_seconds':max(setup),'worst_case_iterations':75,'max_trials_per_iteration':7,'reserve_factor':1.25,'estimated_main_seconds':bound,'measured_peak_host_rss_bytes':peak,'within_45min':bound<2700.,'within_8GiB':peak<8*1024**3}
 save('calibration.json',result);print(json.dumps({k:v for k,v in result.items() if k!='measurements'},indent=2),flush=True)

def main_run():
 estimate=json.loads((D/'calibration.json').read_text());assert estimate['within_45min'] and estimate['within_8GiB'],'STOP before main: calibration over packet budget'
 assert estimate['criteria_freeze_sha256']==sha(D/'criteria-input-freeze.json')
 info=run(D/'main-gpu','cuda',(1,1),main=True);save('main-outcome.json',info)

def cpu():
 info=run(D/'cpu-four','cpu',(4,2));result={'run':info,'fields':{}}
 for field in ['vp','vs','rho','qp','qs']:
  c=D/'cpu-four/model'/f'inverted_stage_1_it_4.{field}';g=D/'main-gpu/model'/f'inverted_stage_1_it_4.{field}'
  if not c.exists() or not g.exists():result['fields'][field]={'available':False};continue
  result['fields'][field]={'available':True,'cpu_sha256':sha(c),'gpu_sha256':sha(g),'byte_equal':c.read_bytes()==g.read_bytes()}
 result['byte_equal']=len(result['fields'])==5 and all(v.get('byte_equal',False) for v in result['fields'].values());save('cpu-four-comparison.json',result);print(json.dumps(result,indent=2),flush=True)

def compare():
 result={}
 for name,backend in [('compare-candidate-shot51','cpu'),('compare-koehn-shot51','koehn')]:
  info=run(D/name,backend,(4,2));assert info['returncode']==0,info;result[backend]=info
 difference={}
 for comp in ['x','y']:
  a=b.su(D/'compare-candidate-shot51/su'/f'synthetic_{comp}.su.shot1')[:,1:-1].astype(np.float64);z=b.su(D/'compare-koehn-shot51/su'/f'synthetic_{comp}.su.shot1')[:,1:-1].astype(np.float64)
  assert np.isfinite(a).all() and np.isfinite(z).all();scale=float(np.sum(a*a));assert scale>0
  rel=float(np.sqrt(np.sum((a-z)**2)/scale));difference[comp]={'relative_l2':rel,'limit':1e-3,'within_expectation':rel<=1e-3,'maximum_abs_difference':float(np.max(np.abs(a-z)))}
 save('equal-tau-forward-comparison.json',{'runs':result,'same_fp32_tau':float(np.float32(2/30)),'FL_hz':3,'time_samples':'physical2..NT-1','components':difference,'differences':['candidate legacy mapping mode0/Q30; inversion remains physicalQ80','modern versus b07 historical FP32 literals/solver genealogy','existing package inseis bounds variant retained; no reader is used on output traces']});print(json.dumps(difference,indent=2),flush=True)

def stage_models():
 result={}
 for p in sorted((D/'main-gpu/model').glob('inverted_stage_*_it_*.vp')):
  m=re.search(r'_stage_(\d+)_it_(\d+)\.vp$',p.name);s,i=map(int,m.groups())
  if s not in result or i>result[s][0]:result[s]=(i,p)
 return result

def exported_model(stage,iteration):
 if stage==0:return D/'models/start'
 out=D/'evaluation-models'/f'stage{stage}-iter{iteration}';out.mkdir(parents=True,exist_ok=True)
 for field in ['vp','vs','rho','qp','qs']:
  src=D/'main-gpu/model'/f'inverted_stage_{stage}_it_{iteration}.{field}';dest=out/('model.'+field);shutil.copyfile(src,dest);assert sha(src)==sha(dest)
 return out

def objective(c,fc):
 per={}
 for local,shot in enumerate(SHOTS,1):
  total=0.
  for comp in ['x','y']:
   synt=b.su(c/'su'/f'synthetic_{comp}.su.shot{local}');obs=b.filtered(b.su(D/'bank/su'/f'synthetic_{comp}.su.shot{local}'),6,fc)
   r=(synt-obs).astype('<f4').astype(np.float64);assert np.isfinite(r).all();total+=.5*float(np.sum(r[:,1:-1]**2,dtype=np.float64))
  per[shot]=total
 return {'training':sum(per[s] for s in TRAIN),'control_sum':sum(per[s] for s in CONTROL),'per_original_shot':per}

def evaluate():
 frozen=json.loads((D/'criteria-input-freeze.json').read_text());assert frozen['observed_bank_sha256']==json.loads((D/'bank.json').read_text())
 assert all(sha(D/'bank'/p)==value for p,value in frozen['observed_bank_sha256'].items())
 available=stage_models();result={};model_errors={'0':errors(D/'models/start')};previous=(0,0)
 save('external-objectives.json',result);save('model-errors.json',model_errors)
 for stage,fc in enumerate(FREQUENCIES,1):
  if stage not in available:break
  iteration=available[stage][0];current=(stage,iteration);row={}
  for label,pair in [('initial',previous),('final',current)]:
   model=exported_model(*pair);name=f'eval-stage{stage}-{label}-model{pair[0]}-iter{pair[1]}'
   c,layout=case(name,'cuda',0,model=model,source=D/f'stage-source-{fc}.dat',stages=(fc,));info=run(c,'cuda',layout);assert info['returncode']==0,info
   row[label]=dict(**objective(c,fc),run=info)
  result[str(stage)]={'frequency_hz':fc,'iteration':iteration,**row};model_errors[str(stage)]=errors(exported_model(*current));previous=current
  save('external-objectives.json',result);save('model-errors.json',model_errors)
 info=json.loads((D/'main-gpu/run.json').read_text());misfit=[]
 for line in (D/'main-gpu/misfit.log').read_text().splitlines():misfit.append([float(v) for v in line.split()])
 reports=[json.loads(p.read_text()) for p in sorted((D/'main-gpu/lifecycle').glob('*.json'))];counts={str(s):{'iterations':sum(int(row[-1])==s for row in misfit),'trial_attempts':0,'trial_forward_batches':0} for s in [1,2,3]}
 for report in reports:
  stage=int(re.search(r'_stage_(\d+)_it_',report['persisted_prefix'])[1]);counts[str(stage)]['trial_attempts']+=report['alphas_attempted'];counts[str(stage)]['trial_forward_batches']+=report['trial_forwards_max']
 models_finite=True
 for p in (D/'main-gpu/model').glob('inverted_stage_*_it_*.*'):
  if p.suffix.lstrip('.') in ['vp','vs','rho','qp','qs']:models_finite&=bool(np.isfinite(np.fromfile(p,dtype='<f4')).all())
 finite=all(math.isfinite(v) for row in misfit for v in row) and all(math.isfinite(t['objective']) for r in reports for t in r['trials'])
 complete=info['returncode']==0 and list(sorted(available))==[1,2,3] and all(1<=counts[str(s)]['iterations']<=25 for s in [1,2,3])
 assert len(reports)==len(misfit),('Lifecycle archive incomplete, do not invent trial counts',len(reports),len(misfit))
 cpucheck=json.loads((D/'cpu-four-comparison.json').read_text());criteria={}
 criteria['K1']={'passed':bool(complete and models_finite and finite),'program_complete':complete,'models_finite':bool(models_finite),'misfits_finite':bool(finite),'stage_counts':counts}
 for key,metric in [('K2','training'),('K3','control_sum')]:
  values={s:{'initial':v['initial'][metric],'final':v['final'][metric],'passed':v['final'][metric]<v['initial'][metric]} for s,v in result.items()}
  criteria[key]={'passed':len(values)==3 and all(v['passed'] for v in values.values()),'stages':values}
 if complete:
  final=model_errors['3'];start=model_errors['0'];upper_rel=(start['vs']['upper']['relative_l2']-final['vs']['upper']['relative_l2'])/start['vs']['upper']['relative_l2']
  criteria['K4']={'passed':all(final['vs'][region]['relative_l2']<start['vs'][region]['relative_l2'] for region in ['total','upper','middle']) and final['vs']['upper']['relative_l2']<=frozen['criteria']['K4']['upper_vs_final_le'],'initial':start['vs'],'final':final['vs'],'upper_relative_reduction':upper_rel,'required_upper_reduction':.02}
  criteria['K5']={'passed':final['vp']['total']['relative_l2']<=start['vp']['total']['relative_l2'],'initial':start['vp']['total']['relative_l2'],'final':final['vp']['total']['relative_l2']}
 else:
  criteria['K4']={'passed':False,'status':'NOT_EVALUABLE: target3-stage endpoint absent; last valid model reported separately'};criteria['K5']=dict(criteria['K4'])
 criteria['K6']={'passed':cpucheck['byte_equal'],'fields':cpucheck['fields']}
 save('criteria-results.json',{'criteria_freeze_sha256':sha(D/'criteria-input-freeze.json'),'K1_K6':criteria,'status':'MECHANICAL CRITERIA ONLY, independent review/external audit required','last_valid_models':{str(s):i[0] for s,i in available.items()}});print(json.dumps(criteria,indent=2),flush=True)

def resource_outcome():
 assert not (D/'main-gpu/run.json').exists() and not (D/'cpu-four/run.json').exists()
 frozen=json.loads((D/'criteria-input-freeze.json').read_text());cal=json.loads((D/'calibration.json').read_text());assert not cal['within_45min']
 criteria={k:{'status':'NOT_EVALUATED','passed':None,'reason':'GPU main not started: frozen pre-run resource estimate exceeds45min'} for k in ['K1','K2','K3','K4','K5','K6']}
 criteria['K1'].update(main_started=False,completed_stages=0,expected_stages=3)
 criteria['K4'].update(initial=frozen['initial_errors']['vs'],upper_final_target_le=frozen['criteria']['K4']['upper_vs_final_le'],final=None)
 criteria['K5'].update(initial=frozen['initial_errors']['vp']['total']['relative_l2'],final=None)
 criteria['K6'].update(cpu_four_started=False,gpu_steps_available_for_pair=0)
 save('criteria-results.json',{'status':'RESOURCE_STOP_BEFORE_MAIN; NOT a numerical K1-K6 failure','criteria_freeze_sha256':sha(D/'criteria-input-freeze.json'),'K1_K6':criteria,'main_started':False,'independent_review_and_external_audit_required':True})
 save('cpu-four-comparison.json',{'status':'NOT_EVALUATED','cpu_four_started':False,'reason':'No corresponding GPU4 steps; no CPU inverse run'})
 save('model-errors.json',{'0':frozen['initial_errors'],'endpoint':None,'status':'No inversion endpoint exists'})
 # Reuse only already-computed first-band forward traces; no new wave solve.
 phi={};c=D/'cal-forward-2.5'
 for local,shot in enumerate(TRAIN,1):
  total=0.
  for comp in ['x','y']:
   a=b.su(c/'su'/f'synthetic_{comp}.su.shot{local}');o=b.filtered(b.su(D/'bank/su'/f'synthetic_{comp}.su.shot{local}'),6,2.5)
   r=(a-o).astype('<f4').astype(np.float64);assert np.isfinite(r).all();total+=.5*float(np.sum(r[:,1:-1]**2,dtype=np.float64))
  phi[shot]=total
 save('external-objectives.json',{'status':'Initial-only diagnostic, no final/control comparisons and no K2/K3 verdict','frequency_hz':2.5,'model':'unchanged start','training':sum(phi.values()),'per_training_shot':phi,'control_sum':None,'endpoint':None,'source':'Reused completed calibration forward, same unchanged numerical operators; no repeat solve'})
 print('K1-K6 NOT_EVALUATED; resource stop, no endpoint invented.',flush=True)


def plots():
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 frozen=json.loads((D/'criteria-input-freeze.json').read_text());models=stage_models();outcome=json.loads((D/'criteria-results.json').read_text());not_started=outcome.get('main_started') is False
 if not_started:
  panels=[('Start',D/'models/start'),('Wahrheit',D/'models/truth')];caption='RessourcenSTOP vor Hauptlauf — kein Endmodell vorhanden'
 else:
  last=max(models);iteration=models[last][0];end=exported_model(last,iteration)
  complete=outcome['K1_K6']['K1']['program_complete'];label='Ende' if complete else f'Letztes gültiges Modell: Stufe{last},Iter{iteration}'
  panels=[('Start',D/'models/start'),(label,end),('Wahrheit',D/'models/truth')];caption=label
 figures={}
 for field in ['vp','vs']:
  lo,hi=frozen['figures']['limits'][field];fig,axes=plt.subplots(1,len(panels),figsize=(5*len(panels),5),sharey=True,layout='constrained')
  for ax,(name,folder) in zip(axes,panels):
   a=np.fromfile(folder/('model.'+field),dtype='<f4').reshape(500,152).T
   im=ax.imshow(a,origin='upper',extent=(.01,10.01,3.05,.01),vmin=lo,vmax=hi,cmap='viridis',aspect='auto',interpolation='nearest');ax.set_title(name);ax.set_xlabel('x [km]');ax.axhspan(.01,.21,color='white',alpha=.15)
  axes[0].set_ylabel('Tiefe im Festkörper-Crop [km]');fig.colorbar(im,ax=axes,label=field.upper()+' [m/s]',shrink=.75);fig.suptitle('B3-S R5 — '+field.upper()+'\n'+caption)
  path=D/f'models-{field}.png';fig.savefig(path,dpi=170);plt.close(fig);figures[field]={'path':str(path),'sha256':sha(path),'vmin_m_s':lo,'vmax_m_s':hi,'panels':[a[0] for a in panels],'caption':caption}
 save('figures.json',figures);print(json.dumps(figures,indent=2))

