 paths=[D/'criteria-input-freeze.json',D/'model-ratio-precheck.json',D/'bank.json',D/'calibration.json',D/'criteria-results.json',D/'external-objectives.json',D/'model-errors.json',D/'cpu-four-comparison.json',D/'equal-tau-forward-comparison.json',D/'models-vp.png',D/'models-vs.png',D/'timing-denise-cuda',*BINARY.values()]
 head=subprocess.check_output(['git','-C',str(W),'rev-parse','HEAD'],text=True).strip();tree=subprocess.check_output(['git','-C',str(W),'rev-parse',head+'^{tree}'],text=True).strip()
 labels={str(BINARY['cpu']):'CPU-standard-denise',str(BINARY['cuda']):'GPU-NoFMA-standard-denise_cuda',str(BINARY['koehn']):'Koehn-b07d81d-R3-IObounds'}
